    "CAUSE_DECES" CHARACTER VARYING(255),
    "CIN" CHARACTER VARYING(30) NOT NULL,
    "DATE_DECES" DATE,
    "DATE_NAISSANCE" DATE NOT NULL,
    "DATE_RADIATION" DATE,
    "DERNIER_UNITE" CHARACTER VARYING(120) NOT NULL,
